// Generadores de ejercicios por tema: cada uno arma un problema con datos al
// azar (semilla reproducible), su respuesta exacta y la resolución paso a paso
// como en el cuaderno (fórmula → reemplazo → resultado). Así hay práctica
// ilimitada y la corrección es automática, también sin internet.
// Fórmulas de física estándar (ver FORMULA_NOTE en sources.js).

const G_EARTH = 9.8;
const C_LIGHT = 3e8;
const K_COULOMB = 9e9;
const G_UNIV = 6.67e-11;
const E_CHARGE = 1.6e-19;
const H_PLANCK = 6.63e-34;
const V_SOUND = 340;
const DEG = Math.PI / 180;

/* ---------- utilidades numéricas ---------- */

export function seededRandom(seed) {
  let a = (Number(seed) >>> 0) || 1;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const pick = (rng, list) => list[Math.floor(rng() * list.length)];
const int = (rng, min, max) => min + Math.floor(rng() * (max - min + 1));

const SUPERSCRIPT = { '-': '⁻', 0: '⁰', 1: '¹', 2: '²', 3: '³', 4: '⁴', 5: '⁵', 6: '⁶', 7: '⁷', 8: '⁸', 9: '⁹' };
// Miles con espacio fino (5 400) y coma decimal: así "5.400" nunca se
// confunde con 5,4 cuando el alumno copia el número.
const plain = (value, decimals) => new Intl.NumberFormat('es-PY', { maximumFractionDigits: decimals, minimumFractionDigits: 0 })
  .formatToParts(value).map(part => (part.type === 'group' ? ' ' : part.value)).join('');

/** Número con coma decimal; muy grandes o muy chicos en notación científica. */
export function fmt(value, decimals = 2) {
  if (!Number.isFinite(value)) return '—';
  const abs = Math.abs(value);
  if (abs !== 0 && (abs >= 1e6 || abs < 1e-3)) {
    const exponent = Math.floor(Math.log10(abs));
    const mantissa = value / 10 ** exponent;
    return `${plain(mantissa, 2)} × 10${String(exponent).split('').map(char => SUPERSCRIPT[char] ?? char).join('')}`;
  }
  return plain(value, abs < 1 ? Math.max(decimals, 3) : decimals);
}

/** Lee lo que escribe el alumno: "1,5", "1.5", "2,1e14", "2,1 × 10^14", "2,1·10¹⁴". */
export function parseUserNumber(input) {
  if (typeof input === 'number') return input;
  let text = String(input ?? '').trim().toLowerCase().replace(/\s+/g, '');
  if (!/\d/.test(text)) return NaN;
  const superMap = { '⁻': '-', '⁰': '0', '¹': '1', '²': '2', '³': '3', '⁴': '4', '⁵': '5', '⁶': '6', '⁷': '7', '⁸': '8', '⁹': '9' };
  text = text.replace(/[⁻⁰¹²³⁴⁵⁶⁷⁸⁹]/g, char => superMap[char]);
  text = text.replace(/[−–]/g, '-');
  text = text.replace(/[x×·*]10\^?/g, 'e');
  // Separadores: si hay coma, la coma es decimal y los puntos son de miles.
  if (text.includes(',')) text = text.replace(/\.(?=\d{3}(\D|$))/g, '').replace(',', '.');
  text = text.replace(/[^0-9eE+\-.]/g, '');
  const value = Number(text);
  return Number.isFinite(value) ? value : NaN;
}

const L = (es, gn) => ({ es, gn });

/**
 * Arma el ejercicio. `ask` es el símbolo que se pide; `formula` la ecuación;
 * `subst` el reemplazo con números; `answer` el resultado exacto.
 */
function make({ prompt, data, ask, formula, subst, answer, unit = '', decimals = 2, tolAbs, hint }) {
  return {
    prompt,
    data,
    ask,
    formula,
    steps: [formula, subst, `${ask} = ${fmt(answer, decimals)}${unit ? ` ${unit}` : ''}`],
    answer,
    unit,
    decimals,
    tolAbs,
    hint: hint ?? L(`Usá ${formula}.`, `Eipuru ${formula}.`),
  };
}
const d = (sym, value, unit = '', decimals = 2) => ({ sym, value: fmt(value, decimals), unit });

/* ---------- generadores por tema ---------- */

const GENERATORS = {
  // Magnitudes
  'units-kmh': rng => { const v = pick(rng, [18, 36, 54, 72, 90, 108, 126]); return make({ prompt: L(`Un colectivo va por la ruta a ${v} km/h. ¿Cuánto es en m/s?`, `Peteĩ colectivo oho ruta-pe ${v} km/h-pe. ¿Mboýpa m/s-pe?`), data: [d('v', v, 'km/h')], ask: 'v', formula: 'v (m/s) = v (km/h) / 3,6', subst: `v = ${v} / 3,6`, answer: v / 3.6, unit: 'm/s' }); },
  'units-ms': rng => { const v = pick(rng, [5, 10, 15, 20, 25, 30, 35]); return make({ prompt: L(`Un dron vuela a ${v} m/s. ¿Cuánto es en km/h?`, `Peteĩ dron ovevé ${v} m/s-pe. ¿Mboýpa km/h-pe?`), data: [d('v', v, 'm/s')], ask: 'v', formula: 'v (km/h) = v (m/s) · 3,6', subst: `v = ${v} · 3,6`, answer: v * 3.6, unit: 'km/h' }); },
  'units-mass': rng => { const g = pick(rng, [250, 500, 750, 1500, 2500, 3200]); return make({ prompt: L(`Un paquete de yerba pesa ${g} g. ¿Cuántos kilogramos son?`, `Peteĩ yerba paquete ipohýi ${g} g. ¿Mboy kilogramo?`), data: [d('m', g, 'g')], ask: 'm', formula: 'm (kg) = m (g) / 1000', subst: `m = ${g} / 1000`, answer: g / 1000, unit: 'kg', decimals: 3 }); },
  'units-time': rng => { const m = pick(rng, [15, 20, 45, 90, 35, 12]); return make({ prompt: L(`Un partido de fútbol de ${m} minutos. ¿Cuántos segundos son?`, `Peteĩ partido ${m} minuto. ¿Mboy segundo?`), data: [d('t', m, 'min')], ask: 't', formula: 't (s) = t (min) · 60', subst: `t = ${m} · 60`, answer: m * 60, unit: 's' }); },

  // Vectores
  'vec-resultant': rng => { const [a, b] = pick(rng, [[3, 4], [6, 8], [5, 12], [8, 15], [9, 12], [12, 16], [7, 24]]); const k = pick(rng, [1, 10, 20]); return make({ prompt: L(`Caminás ${a * k} m hacia el este y después ${b * k} m hacia el norte. ¿A qué distancia en línea recta quedaste del punto de partida?`, `Reguata ${a * k} m este gotyo ha upéi ${b * k} m norte gotyo. ¿Mboy distancia-pe reime reñepyrũhágui línea recta-pe?`), data: [d('A', a * k, 'm'), d('B', b * k, 'm')], ask: 'R', formula: 'R = √(A² + B²)', subst: `R = √(${a * k}² + ${b * k}²)`, answer: Math.hypot(a * k, b * k), unit: 'm' }); },
  'vec-components': rng => { const A = pick(rng, [10, 20, 30, 40, 50, 80]); const th = pick(rng, [30, 37, 45, 53, 60]); return make({ prompt: L(`Una cuerda tira de un carrito con ${A} N formando ${th}° con el suelo. ¿Cuánto vale la componente horizontal de la fuerza?`, `Peteĩ cuerda omosẽ carrito ${A} N reheve ${th}° yvy ndive. ¿Mboýpa fuerza componente horizontal?`), data: [d('F', A, 'N'), d('θ', th, '°')], ask: 'F_{x}', formula: 'F_{x} = F · cos θ', subst: `F_{x} = ${A} · cos ${th}°`, answer: A * Math.cos(th * DEG), unit: 'N' }); },
  'vec-dot': rng => { const A = pick(rng, [2, 3, 4, 5, 6]); const B = pick(rng, [2, 4, 5, 8, 10]); const th = pick(rng, [0, 30, 45, 60, 120]); return make({ prompt: L(`Dos vectores de módulos ${A} y ${B} forman un ángulo de ${th}°. ¿Cuánto vale su producto punto?`, `Mokõi vector módulo ${A} ha ${B} ojapo ángulo ${th}°. ¿Mboýpa producto punto?`), data: [d('A', A), d('B', B), d('θ', th, '°')], ask: 'A·B', formula: 'A·B = A · B · cos θ', subst: `A·B = ${A} · ${B} · cos ${th}°`, answer: A * B * Math.cos(th * DEG), tolAbs: 0.05 }); },

  // Características del movimiento
  'cin-mean-speed': rng => { const t = pick(rng, [20, 40, 50, 80, 100, 200]); const v = pick(rng, [2, 3, 4, 5, 6, 8]); const dist = v * t; return make({ prompt: L(`Una ciclista recorre ${dist} m de la costanera en ${t} s. ¿Cuál es su rapidez media?`, `Peteĩ ciclista oguata ${dist} m costanera-pe ${t} s-pe. ¿Mboýpa irapidez media?`), data: [d('d', dist, 'm'), d('t', t, 's')], ask: 'v_{m}', formula: 'v_{m} = d / t', subst: `v_{m} = ${dist} / ${t}`, answer: dist / t, unit: 'm/s' }); },
  'cin-mean-accel': rng => { const v0 = pick(rng, [0, 2, 4, 5]); const vf = v0 + pick(rng, [6, 8, 10, 12, 15]); const t = pick(rng, [2, 3, 4, 5]); return make({ prompt: L(`Una moto pasa de ${v0} m/s a ${vf} m/s en ${t} s. ¿Cuál es su aceleración media?`, `Peteĩ moto ohasa ${v0} m/s guive ${vf} m/s peve ${t} s-pe. ¿Mboýpa iaceleración media?`), data: [d('v_{0}', v0, 'm/s'), d('v_{f}', vf, 'm/s'), d('t', t, 's')], ask: 'a_{m}', formula: 'a_{m} = (v_{f} − v_{0}) / t', subst: `a_{m} = (${vf} − ${v0}) / ${t}`, answer: (vf - v0) / t, unit: 'm/s²' }); },

  // MRU
  'mru-distance': rng => { const v = int(rng, 8, 30); const t = pick(rng, [5, 8, 10, 12, 15, 20, 30]); return make({ prompt: L(`Un camión va por la Ruta 2 a velocidad constante de ${v} m/s. ¿Qué distancia recorre en ${t} s?`, `Peteĩ camión oho Ruta 2-pe velocidad constante ${v} m/s-pe. ¿Mboy distancia oguata ${t} s-pe?`), data: [d('v', v, 'm/s'), d('t', t, 's')], ask: 'd', formula: 'd = v · t', subst: `d = ${v} · ${t}`, answer: v * t, unit: 'm' }); },
  'mru-time': rng => { const v = pick(rng, [10, 12, 15, 20, 25]); const t = pick(rng, [8, 12, 20, 30, 40]); const dist = v * t; return make({ prompt: L(`Un tren de carga avanza a ${v} m/s. ¿Cuánto tarda en recorrer ${dist} m?`, `Peteĩ tren oho ${v} m/s-pe. ¿Mboy tiempo oipuru oguata hag̃ua ${dist} m?`), data: [d('d', dist, 'm'), d('v', v, 'm/s')], ask: 't', formula: 't = d / v', subst: `t = ${dist} / ${v}`, answer: t, unit: 's' }); },
  'mru-meet': rng => { const v1 = pick(rng, [8, 10, 12, 15]); const v2 = pick(rng, [5, 6, 10, 15]); const t = pick(rng, [10, 20, 25, 40]); const D = (v1 + v2) * t; return make({ prompt: L(`Dos motos salen al mismo tiempo de los extremos de un camino de ${D} m, una hacia la otra, a ${v1} m/s y ${v2} m/s. ¿En cuánto tiempo se encuentran?`, `Mokõi moto osẽ oñondive tape ${D} m apýgui, ojoupe gotyo, ${v1} m/s ha ${v2} m/s-pe. ¿Mboy tiempo-pe ojotopa?`), data: [d('D', D, 'm'), d('v_{1}', v1, 'm/s'), d('v_{2}', v2, 'm/s')], ask: 't', formula: 't = D / (v_{1} + v_{2})', subst: `t = ${D} / (${v1} + ${v2})`, answer: t, unit: 's', hint: L('Se acercan con la suma de sus velocidades.', 'Oñembojaháicha velocidad suma reheve.') }); },

  // MRUV
  'mruv-final-speed': rng => { const v0 = pick(rng, [0, 5, 8, 10, 12]); const a = pick(rng, [1.5, 2, 2.5, 3, 4]); const t = pick(rng, [3, 4, 5, 6, 8]); return make({ prompt: L(`Un auto va a ${fmt(v0)} m/s y acelera a ${fmt(a)} m/s² durante ${t} s. ¿Cuál es su velocidad final?`, `Peteĩ auto oho ${fmt(v0)} m/s-pe ha oacelera ${fmt(a)} m/s² ${t} s aja. ¿Mboýpa ivelocidad final?`), data: [d('v_{0}', v0, 'm/s'), d('a', a, 'm/s²'), d('t', t, 's')], ask: 'v', formula: 'v = v0 + a · t', subst: `v = ${fmt(v0)} + ${fmt(a)} · ${t}`, answer: v0 + a * t, unit: 'm/s' }); },
  'mruv-distance': rng => { const a = pick(rng, [1, 2, 3, 4, 5]); const t = pick(rng, [2, 3, 4, 5, 6, 8, 10]); return make({ prompt: L(`Una moto parte del reposo en el semáforo con aceleración de ${a} m/s². ¿Qué distancia recorre en ${t} s?`, `Peteĩ moto osẽ reposo-gui semáforo-pe aceleración ${a} m/s² reheve. ¿Mboy distancia oguata ${t} s-pe?`), data: [d('v_{0}', 0, 'm/s'), d('a', a, 'm/s²'), d('t', t, 's')], ask: 'd', formula: 'd = ½ a · t²', subst: `d = ½ · ${a} · ${t}²`, answer: 0.5 * a * t * t, unit: 'm' }); },
  'mruv-brake': rng => { const v0 = pick(rng, [10, 12, 15, 20, 25]); const a = pick(rng, [2, 2.5, 4, 5, 6]); return make({ prompt: L(`Un colectivo que va a ${v0} m/s frena con una desaceleración de ${fmt(a)} m/s². ¿Cuántos metros necesita para detenerse?`, `Peteĩ colectivo oho ${v0} m/s-pe ha ofrena ${fmt(a)} m/s² reheve. ¿Mboy metro oikotevẽ opyta hag̃ua?`), data: [d('v_{0}', v0, 'm/s'), d('a', -a, 'm/s²'), d('v_{f}', 0, 'm/s')], ask: 'd', formula: 'd = v0² / (2a)', subst: `d = ${v0}² / (2 · ${fmt(a)})`, answer: v0 * v0 / (2 * a), unit: 'm', hint: L('Usá Torricelli con velocidad final cero.', 'Eipuru Torricelli velocidad final cero reheve.') }); },

  // Movimiento vertical en el vacío
  'ff-time': rng => { const h = pick(rng, [5, 10, 20, 30, 45, 80]); return make({ prompt: L(`Se deja caer una piedra desde un puente de ${h} m (sin aire). ¿Cuánto tarda en llegar al agua?`, `Ojeheja ho’a peteĩ ita puente ${h} m-gui (aire’ỹre). ¿Mboy tiempo og̃uahẽ hag̃ua ýpe?`), data: [d('h', h, 'm'), d('g', G_EARTH, 'm/s²')], ask: 't', formula: 't = √(2h / g)', subst: `t = √(2 · ${h} / 9,8)`, answer: Math.sqrt(2 * h / G_EARTH), unit: 's' }); },
  'ff-speed': rng => { const t = pick(rng, [1, 1.5, 2, 2.5, 3, 4]); return make({ prompt: L(`Un mango cae libremente desde el árbol durante ${fmt(t)} s. ¿Con qué velocidad llega al suelo?`, `Peteĩ mango ho’a yvyramáta-gui ${fmt(t)} s aja. ¿Mba’e velocidad-pe og̃uahẽ yvýpe?`), data: [d('t', t, 's'), d('g', G_EARTH, 'm/s²')], ask: 'v', formula: 'v = g · t', subst: `v = 9,8 · ${fmt(t)}`, answer: G_EARTH * t, unit: 'm/s' }); },
  'ff-hmax': rng => { const v0 = pick(rng, [9.8, 14.7, 19.6, 24.5, 29.4]); return make({ prompt: L(`Se lanza una pelota hacia arriba a ${fmt(v0)} m/s. ¿Qué altura máxima alcanza?`, `Oñemombo peteĩ pelota yvate gotyo ${fmt(v0)} m/s-pe. ¿Mboy altura máxima ohupyty?`), data: [d('v_{0}', v0, 'm/s'), d('g', G_EARTH, 'm/s²')], ask: 'H_{máx}', formula: 'H_{máx} = v0² / (2g)', subst: `H_{máx} = ${fmt(v0)}² / (2 · 9,8)`, answer: v0 * v0 / (2 * G_EARTH), unit: 'm' }); },

  // Movimiento parabólico
  'proj-range': rng => { const v = pick(rng, [10, 12, 15, 18, 20, 25]); const th = pick(rng, [30, 37, 45, 53, 60]); return make({ prompt: L(`Una pelota sale a ${v} m/s con ${th}° sobre la horizontal (mismo nivel, sin aire). ¿Cuál es su alcance?`, `Peteĩ pelota osẽ ${v} m/s-pe ${th}° horizontal ári (peteĩ nivel, aire’ỹre). ¿Mboýpa ialcance?`), data: [d('v_{0}', v, 'm/s'), d('θ', th, '°'), d('g', G_EARTH, 'm/s²')], ask: 'R', formula: 'R = v0² · sen(2θ) / g', subst: `R = ${v}² · sen(${2 * th}°) / 9,8`, answer: v * v * Math.sin(2 * th * DEG) / G_EARTH, unit: 'm' }); },
  'proj-hmax': rng => { const v = pick(rng, [10, 14, 15, 20, 25]); const th = pick(rng, [30, 45, 60]); return make({ prompt: L(`Un dron suelta un paquete que sale a ${v} m/s con ${th}°. ¿Qué altura máxima alcanza sobre el punto de salida?`, `Peteĩ dron oheja paquete osẽva ${v} m/s-pe ${th}° reheve. ¿Mboy altura máxima ohupyty?`), data: [d('v_{0}', v, 'm/s'), d('θ', th, '°')], ask: 'Hmax', formula: 'Hmax = v0² · sen²θ / (2g)', subst: `Hmax = ${v}² · sen²(${th}°) / (2 · 9,8)`, answer: (v * Math.sin(th * DEG)) ** 2 / (2 * G_EARTH), unit: 'm' }); },
  'proj-time': rng => { const v = pick(rng, [10, 15, 20, 24, 30]); const th = pick(rng, [30, 45, 60]); return make({ prompt: L(`Un tiro libre sale a ${v} m/s con ${th}° (mismo nivel). ¿Cuánto tiempo está la pelota en el aire?`, `Peteĩ tiro libre osẽ ${v} m/s-pe ${th}° reheve. ¿Mboy tiempo pelota oĩ yvágape?`), data: [d('v_{0}', v, 'm/s'), d('θ', th, '°')], ask: 'T', formula: 'T = 2 · v0 · sen θ / g', subst: `T = 2 · ${v} · sen ${th}° / 9,8`, answer: 2 * v * Math.sin(th * DEG) / G_EARTH, unit: 's' }); },

  // Movimiento circular
  'circ-period': rng => { const n = pick(rng, [4, 5, 8, 10, 12]); const T = pick(rng, [2, 3, 4, 5, 6, 8]); const t = n * T; return make({ prompt: L(`Una calesita da ${n} vueltas en ${t} s. ¿Cuál es su período?`, `Peteĩ calesita ojere ${n} vuelta ${t} s-pe. ¿Mboýpa iperíodo?`), data: [d('n', n), d('t', t, 's')], ask: 'T', formula: 'T = t / n', subst: `T = ${t} / ${n}`, answer: T, unit: 's' }); },
  'circ-speed': rng => { const r = pick(rng, [0.3, 0.35, 0.5, 1, 2, 4]); const T = pick(rng, [0.5, 1, 2, 4, 8]); return make({ prompt: L(`Un punto en el borde de una rueda de radio ${fmt(r)} m da una vuelta cada ${fmt(T)} s. ¿Cuál es su velocidad tangencial?`, `Peteĩ punto rueda radio ${fmt(r)} m rembe’ýpe ojere peteĩ vuelta káda ${fmt(T)} s. ¿Mboýpa ivelocidad tangencial?`), data: [d('r', r, 'm'), d('T', T, 's')], ask: 'v', formula: 'v = 2π · r / T', subst: `v = 2π · ${fmt(r)} / ${fmt(T)}`, answer: 2 * Math.PI * r / T, unit: 'm/s' }); },
  'circ-accel': rng => { const v = pick(rng, [10, 12, 15, 20]); const r = pick(rng, [20, 25, 40, 50, 80]); return make({ prompt: L(`Un auto toma una rotonda de radio ${r} m a ${v} m/s. ¿Cuál es su aceleración centrípeta?`, `Peteĩ auto ohasa rotonda radio ${r} m ${v} m/s-pe. ¿Mboýpa iaceleración centrípeta?`), data: [d('v', v, 'm/s'), d('r', r, 'm')], ask: 'a_{c}', formula: 'a_{c} = v² / r', subst: `a_{c} = ${v}² / ${r}`, answer: v * v / r, unit: 'm/s²' }); },
  'circ-force': rng => { const m = pick(rng, [800, 1000, 1200, 1500]); const v = pick(rng, [10, 15, 20]); const r = pick(rng, [25, 40, 50, 100]); return make({ prompt: L(`Un auto de ${m} kg recorre una curva de radio ${r} m a ${v} m/s. ¿Qué fuerza centrípeta necesita?`, `Peteĩ auto ${m} kg ohasa curva radio ${r} m ${v} m/s-pe. ¿Mboy fuerza centrípeta oikotevẽ?`), data: [d('m', m, 'kg'), d('v', v, 'm/s'), d('r', r, 'm')], ask: 'F_{c}', formula: 'F_{c} = m · v² / r', subst: `F_{c} = ${m} · ${v}² / ${r}`, answer: m * v * v / r, unit: 'N' }); },

  // Newton
  'newton-accel': rng => { const m = pick(rng, [2, 4, 5, 8, 10, 20]); const F = m * pick(rng, [1.5, 2, 2.5, 3, 4]); return make({ prompt: L(`Empujás un carrito de ${m} kg con una fuerza neta de ${fmt(F)} N. ¿Qué aceleración tiene?`, `Remosẽ peteĩ carrito ${m} kg fuerza neta ${fmt(F)} N reheve. ¿Mba’e aceleración oguereko?`), data: [d('F', F, 'N'), d('m', m, 'kg')], ask: 'a', formula: 'a = F / m', subst: `a = ${fmt(F)} / ${m}`, answer: F / m, unit: 'm/s²' }); },
  'newton-force': rng => { const m = pick(rng, [50, 60, 75, 900, 1200]); const a = pick(rng, [0.5, 1, 2, 3]); return make({ prompt: L(`¿Qué fuerza neta hace falta para acelerar ${m} kg a ${fmt(a)} m/s²?`, `¿Mboy fuerza neta oikotevẽ ñamoacelera hag̃ua ${m} kg ${fmt(a)} m/s²-pe?`), data: [d('m', m, 'kg'), d('a', a, 'm/s²')], ask: 'F', formula: 'F = m · a', subst: `F = ${m} · ${fmt(a)}`, answer: m * a, unit: 'N' }); },
  'newton-weight': rng => { const m = pick(rng, [5, 25, 50, 60, 70, 80]); return make({ prompt: L(`¿Cuánto pesa (en newtons) una bolsa de ${m} kg en la Tierra?`, `¿Mboy ipohýi (newton-pe) peteĩ vosa ${m} kg Yvy-pe?`), data: [d('m', m, 'kg'), d('g', G_EARTH, 'm/s²')], ask: 'P', formula: 'P = m · g', subst: `P = ${m} · 9,8`, answer: m * G_EARTH, unit: 'N' }); },
  'newton-incline': rng => { const th = pick(rng, [30, 37, 45, 53]); const mu = pick(rng, [0, 0.1, 0.2, 0.3]); return make({ prompt: L(`Un bloque baja por un plano inclinado de ${th}° con coeficiente de rozamiento μ = ${fmt(mu)}. ¿Cuál es su aceleración?`, `Peteĩ bloque oguejy plano inclinado ${th}°-pe rozamiento μ = ${fmt(mu)} reheve. ¿Mboýpa iaceleración?`), data: [d('θ', th, '°'), d('μ', mu), d('g', G_EARTH, 'm/s²')], ask: 'a', formula: 'a = g · (sen θ − μ · cos θ)', subst: `a = 9,8 · (sen ${th}° − ${fmt(mu)} · cos ${th}°)`, answer: G_EARTH * (Math.sin(th * DEG) - mu * Math.cos(th * DEG)), unit: 'm/s²' }); },
  'newton-atwood': rng => { const m2 = pick(rng, [1, 2, 3, 4]); const m1 = m2 + pick(rng, [1, 2, 3]); return make({ prompt: L(`Máquina de Atwood: dos masas de ${m1} kg y ${m2} kg cuelgan de una polea ideal. ¿Con qué aceleración se mueven?`, `Atwood máquina: mokõi masa ${m1} kg ha ${m2} kg oñekuã polea ideal-gui. ¿Mba’e aceleración-pe oguata?`), data: [d('m_{1}', m1, 'kg'), d('m_{2}', m2, 'kg')], ask: 'a', formula: 'a = (m_{1} − m_{2}) · g / (m_{1} + m_{2})', subst: `a = (${m1} − ${m2}) · 9,8 / (${m1} + ${m2})`, answer: (m1 - m2) * G_EARTH / (m1 + m2), unit: 'm/s²' }); },

  // Equilibrio
  'eq-torque': rng => { const F = pick(rng, [20, 30, 40, 50, 80]); const dd = pick(rng, [0.2, 0.25, 0.3, 0.4, 0.5]); return make({ prompt: L(`Aplicás ${F} N perpendicular a una llave de ${fmt(dd)} m. ¿Qué momento (torque) hacés?`, `Reme’ẽ ${F} N perpendicular llave ${fmt(dd)} m-pe. ¿Mba’e momento rejapo?`), data: [d('F', F, 'N'), d('d', dd, 'm')], ask: 'M', formula: 'M = F · d', subst: `M = ${F} · ${fmt(dd)}`, answer: F * dd, unit: 'N·m' }); },
  'eq-lever': rng => { const P1 = pick(rng, [300, 400, 450, 500, 600]); const d1 = pick(rng, [1, 1.2, 1.5, 2]); const d2 = pick(rng, [1.5, 2, 2.5, 3]); return make({ prompt: L(`En un subibaja, una chica de ${P1} N se sienta a ${fmt(d1)} m del centro. ¿Qué peso debe tener quien se siente del otro lado a ${fmt(d2)} m para equilibrar?`, `Subibaja-pe, peteĩ kuñataĩ ${P1} N oguapy ${fmt(d1)} m centro-gui. ¿Mboy ipohýiva’erã oguapýva ambue gotyo ${fmt(d2)} m-pe ojoequilibra hag̃ua?`), data: [d('F_{1}', P1, 'N'), d('d_{1}', d1, 'm'), d('d_{2}', d2, 'm')], ask: 'F_{2}', formula: 'F_{2} = F_{1} · d_{1} / d_{2}', subst: `F_{2} = ${P1} · ${fmt(d1)} / ${fmt(d2)}`, answer: P1 * d1 / d2, unit: 'N' }); },
  'eq-resultant': rng => { const F1 = pick(rng, [120, 150, 200, 250]); const F2 = pick(rng, [80, 100, 130, 180]); return make({ prompt: L(`Dos personas tiran de una caja en sentidos contrarios con ${F1} N y ${F2} N. ¿Cuánto vale la fuerza resultante?`, `Mokõi tapicha omosẽ peteĩ caja sentido ojoavýpe ${F1} N ha ${F2} N reheve. ¿Mboýpa fuerza resultante?`), data: [d('F_{1}', F1, 'N'), d('F_{2}', F2, 'N')], ask: 'R', formula: 'R = F_{1} − F_{2}', subst: `R = ${F1} − ${F2}`, answer: Math.abs(F1 - F2), unit: 'N' }); },

  // Elasticidad
  'hooke-force': rng => { const k = pick(rng, [50, 100, 150, 200, 400]); const x = pick(rng, [2, 4, 5, 8, 10, 15]); return make({ prompt: L(`Un resorte de constante ${k} N/m se estira ${x} cm. ¿Qué fuerza se aplicó?`, `Peteĩ resorte constante ${k} N/m ojepyso ${x} cm. ¿Mba’e fuerza ojeme’ẽ?`), data: [d('k', k, 'N/m'), d('x', x / 100, 'm')], ask: 'F', formula: 'F = k · x', subst: `F = ${k} · ${fmt(x / 100)}`, answer: k * x / 100, unit: 'N', hint: L('Pasá los centímetros a metros primero.', 'Embohasa centímetro metro-pe raẽ.') }); },
  'hooke-k': rng => { const x = pick(rng, [0.02, 0.04, 0.05, 0.1]); const k = pick(rng, [100, 200, 250, 500]); const F = k * x; return make({ prompt: L(`Al colgarle ${fmt(F)} N, un resorte se estira ${fmt(x)} m. ¿Cuál es su constante elástica?`, `Ñañapytĩ ${fmt(F)} N, peteĩ resorte ojepyso ${fmt(x)} m. ¿Mboýpa iconstante elástica?`), data: [d('F', F, 'N'), d('x', x, 'm')], ask: 'k', formula: 'k = F / x', subst: `k = ${fmt(F)} / ${fmt(x)}`, answer: k, unit: 'N/m' }); },
  'hooke-x': rng => { const k = pick(rng, [100, 200, 250, 400, 500]); const F = pick(rng, [5, 10, 20, 25, 40]); return make({ prompt: L(`Un dinamómetro de k = ${k} N/m mide ${F} N. ¿Cuántos centímetros se estiró?`, `Dinamómetro k = ${k} N/m omedi ${F} N. ¿Mboy centímetro ojepyso?`), data: [d('k', k, 'N/m'), d('F', F, 'N')], ask: 'x', formula: 'x = F / k', subst: `x = ${F} / ${k} m`, answer: F / k * 100, unit: 'cm', hint: L('Calculá en metros y pasá a centímetros (× 100).', 'Ecalcula metro-pe ha embohasa centímetro-pe (× 100).') }); },

  // Energía
  'en-kinetic': rng => { const m = pick(rng, [50, 60, 70, 80, 1000]); const v = pick(rng, [2, 4, 5, 6, 10, 15]); return make({ prompt: L(`¿Qué energía cinética tiene una persona (o vehículo) de ${m} kg que va a ${v} m/s?`, `¿Mba’e energía cinética oguereko ${m} kg oho ${v} m/s-pe?`), data: [d('m', m, 'kg'), d('v', v, 'm/s')], ask: 'E_{c}', formula: 'E_{c} = ½ m · v²', subst: `E_{c} = ½ · ${m} · ${v}²`, answer: 0.5 * m * v * v, unit: 'J' }); },
  'en-potential': rng => { const m = pick(rng, [2, 5, 10, 20, 50]); const h = pick(rng, [2, 3, 5, 10, 12]); return make({ prompt: L(`Subís una caja de ${m} kg a un estante de ${h} m. ¿Qué energía potencial gana?`, `Rejupi peteĩ caja ${m} kg estante ${h} m-pe. ¿Mba’e energía potencial ohupyty?`), data: [d('m', m, 'kg'), d('g', G_EARTH, 'm/s²'), d('h', h, 'm')], ask: 'E_{p}', formula: 'E_{p} = m · g · h', subst: `E_{p} = ${m} · 9,8 · ${h}`, answer: m * G_EARTH * h, unit: 'J' }); },
  'en-speed-from-height': rng => { const h = pick(rng, [1.25, 2, 2.5, 3.2, 5, 10]); return make({ prompt: L(`Un chico baja por un tobogán sin rozamiento desde ${fmt(h)} m de altura. ¿Con qué velocidad llega abajo?`, `Peteĩ mitã oguejy tobogán rozamiento’ỹva ${fmt(h)} m-gui. ¿Mba’e velocidad-pe og̃uahẽ yvýpe?`), data: [d('h', h, 'm'), d('g', G_EARTH, 'm/s²')], ask: 'v', formula: 'v = √(2 · g · h)', subst: `v = √(2 · 9,8 · ${fmt(h)})`, answer: Math.sqrt(2 * G_EARTH * h), unit: 'm/s', hint: L('La energía potencial se convierte toda en cinética.', 'Energía potencial oiko cinética-ramo.') }); },
  'en-work': rng => { const F = pick(rng, [20, 40, 50, 100]); const dd = pick(rng, [2, 5, 10, 20]); const th = pick(rng, [0, 30, 60]); return make({ prompt: L(`Tirás de un carrito con ${F} N formando ${th}° con el piso y lo movés ${dd} m. ¿Qué trabajo hacés?`, `Remosẽ carrito ${F} N reheve ${th}° yvy ndive ha remongu’e ${dd} m. ¿Mba’e trabajo rejapo?`), data: [d('F', F, 'N'), d('d', dd, 'm'), d('θ', th, '°')], ask: 'W', formula: 'W = F · d · cos θ', subst: `W = ${F} · ${dd} · cos ${th}°`, answer: F * dd * Math.cos(th * DEG), unit: 'J' }); },
  'en-power': rng => { const m = pick(rng, [50, 100, 200, 500]); const h = pick(rng, [5, 10, 12, 20]); const t = pick(rng, [5, 10, 20, 25, 40]); return make({ prompt: L(`Un motor sube ${m} kg de ladrillos a ${h} m en ${t} s. ¿Qué potencia desarrolla?`, `Peteĩ motor ojupi ${m} kg ladrillo ${h} m-pe ${t} s-pe. ¿Mba’e potencia ojapo?`), data: [d('m', m, 'kg'), d('h', h, 'm'), d('t', t, 's')], ask: 'P', formula: 'P = m · g · h / t', subst: `P = ${m} · 9,8 · ${h} / ${t}`, answer: m * G_EARTH * h / t, unit: 'W' }); },

  // Cantidad de movimiento
  'mom-p': rng => { const m = pick(rng, [0.45, 2, 5, 60, 1000]); const v = pick(rng, [3, 5, 10, 20, 25]); return make({ prompt: L(`¿Qué cantidad de movimiento tiene un cuerpo de ${fmt(m)} kg que va a ${v} m/s?`, `¿Mba’e cantidad de movimiento oguereko cuerpo ${fmt(m)} kg oho ${v} m/s-pe?`), data: [d('m', m, 'kg'), d('v', v, 'm/s')], ask: 'p', formula: 'p = m · v', subst: `p = ${fmt(m)} · ${v}`, answer: m * v, unit: 'kg·m/s' }); },
  'mom-impulse': rng => { const F = pick(rng, [200, 500, 800, 1000]); const t = pick(rng, [0.01, 0.02, 0.05, 0.1]); return make({ prompt: L(`Un pie patea una pelota con ${F} N durante ${fmt(t)} s. ¿Qué impulso recibe la pelota?`, `Py omboty pelota ${F} N reheve ${fmt(t)} s aja. ¿Mba’e impulso ohupyty pelota?`), data: [d('F', F, 'N'), d('Δt', t, 's')], ask: 'I', formula: 'I = F · Δt', subst: `I = ${F} · ${fmt(t)}`, answer: F * t, unit: 'N·s' }); },
  'mom-inelastic': rng => { const m1 = pick(rng, [1, 2, 3, 4]); const v1 = pick(rng, [4, 6, 8, 10]); const m2 = pick(rng, [1, 2, 3]); return make({ prompt: L(`Un carrito de ${m1} kg a ${v1} m/s choca con otro de ${m2} kg en reposo y quedan pegados. ¿Con qué velocidad siguen?`, `Carrito ${m1} kg ${v1} m/s-pe oñembotyry ambue ${m2} kg opytáva ndive ha opyta ojoaju. ¿Mba’e velocidad-pe oho?`), data: [d('m_{1}', m1, 'kg'), d('v_{1}', v1, 'm/s'), d('m_{2}', m2, 'kg')], ask: 'v′', formula: 'v′ = m_{1} · v_{1} / (m_{1} + m_{2})', subst: `v′ = ${m1} · ${v1} / (${m1} + ${m2})`, answer: m1 * v1 / (m1 + m2), unit: 'm/s', hint: L('La cantidad de movimiento total se conserva.', 'Cantidad de movimiento total oñeñongatu.') }); },

  // Gravitación
  'grav-force': rng => { const m = pick(rng, [500, 1000, 1500, 2000]); const r = pick(rng, [7, 8, 10, 12, 20]); const M = 5.97e24; return make({ prompt: L(`¿Con qué fuerza atrae la Tierra (M = 5,97 × 10²⁴ kg) a un satélite de ${m} kg a ${r} × 10⁶ m de su centro?`, `¿Mba’e fuerza reheve Yvy (M = 5,97 × 10²⁴ kg) ombyaty satélite ${m} kg ${r} × 10⁶ m icentro-gui?`), data: [d('M', M, 'kg'), d('m', m, 'kg'), d('d', r * 1e6, 'm'), d('G', G_UNIV, 'N·m²/kg²')], ask: 'F', formula: 'F = G · M · m / d²', subst: `F = 6,67 × 10⁻¹¹ · 5,97 × 10²⁴ · ${m} / (${r} × 10⁶)²`, answer: G_UNIV * M * m / (r * 1e6) ** 2, unit: 'N' }); },
  'grav-distance': rng => { const k = pick(rng, [2, 3, 4, 5]); return make({ prompt: L(`Si la distancia entre dos cuerpos se multiplica por ${k}, ¿por cuánto se divide la fuerza gravitatoria?`, `Mokõi cuerpo distancia oñemultiplicáramo ${k} rehe, ¿mboy rehe oñedividi fuerza gravitatoria?`), data: [d('factor', k)], ask: 'n', formula: 'n = factor²', subst: `n = ${k}²`, answer: k * k, hint: L('F depende de 1/d².', 'F odepende 1/d²-gui.') }); },
  'grav-surface': rng => { const body = pick(rng, [{ es: 'la Luna', gn: 'Jasy', M: 7.35e22, R: 1.737e6 }, { es: 'Marte', gn: 'Marte', M: 6.42e23, R: 3.39e6 }, { es: 'la Tierra', gn: 'Yvy', M: 5.97e24, R: 6.37e6 }]); return make({ prompt: L(`Calculá la gravedad en la superficie de ${body.es} (M = ${fmt(body.M)} kg; R = ${fmt(body.R)} m).`, `Ecalcula gravedad ${body.gn} ape ári (M = ${fmt(body.M)} kg; R = ${fmt(body.R)} m).`), data: [d('M', body.M, 'kg'), d('R', body.R, 'm')], ask: 'g', formula: 'g = G · M / R²', subst: `g = 6,67 × 10⁻¹¹ · ${fmt(body.M)} / (${fmt(body.R)})²`, answer: G_UNIV * body.M / body.R ** 2, unit: 'm/s²' }); },

  // Hidrostática
  'hid-density': rng => { const rho = pick(rng, [800, 920, 1000, 2700, 7800]); const V = pick(rng, [0.001, 0.002, 0.005, 0.01]); const m = rho * V; return make({ prompt: L(`Un bloque de ${fmt(m)} kg ocupa ${fmt(V)} m³. ¿Cuál es su densidad?`, `Peteĩ bloque ${fmt(m)} kg oipuru ${fmt(V)} m³. ¿Mboýpa idensidad?`), data: [d('m', m, 'kg'), d('V', V, 'm³')], ask: 'ρ', formula: 'ρ = m / V', subst: `ρ = ${fmt(m)} / ${fmt(V)}`, answer: rho, unit: 'kg/m³' }); },
  'hid-pressure-depth': rng => { const h = pick(rng, [1, 2, 3, 5, 10]); return make({ prompt: L(`¿Cuánto aumenta la presión a ${h} m de profundidad en una pileta (agua, ρ = 1000 kg/m³)?`, `¿Mboy ojupi presión ${h} m ipypukúpe pileta-pe (y, ρ = 1000 kg/m³)?`), data: [d('ρ', 1000, 'kg/m³'), d('g', G_EARTH, 'm/s²'), d('h', h, 'm')], ask: 'ΔP', formula: 'ΔP = ρ · g · h', subst: `ΔP = 1000 · 9,8 · ${h}`, answer: 1000 * G_EARTH * h, unit: 'Pa' }); },
  'hid-press': rng => { const F1 = pick(rng, [50, 100, 150, 200]); const A1 = pick(rng, [5, 10, 20]); const A2 = A1 * pick(rng, [10, 20, 40, 50]); return make({ prompt: L(`En una prensa hidráulica empujás con ${F1} N un émbolo de ${A1} cm². ¿Qué fuerza aparece en el émbolo de ${A2} cm²?`, `Prensa hidráulica-pe remosẽ ${F1} N émbolo ${A1} cm². ¿Mba’e fuerza osẽ émbolo ${A2} cm²-pe?`), data: [d('F_{1}', F1, 'N'), d('A_{1}', A1, 'cm²'), d('A_{2}', A2, 'cm²')], ask: 'F_{2}', formula: 'F_{2} = F_{1} · A_{2} / A_{1}', subst: `F_{2} = ${F1} · ${A2} / ${A1}`, answer: F1 * A2 / A1, unit: 'N' }); },
  'hid-pressure': rng => { const F = pick(rng, [500, 600, 700, 800]); const A = pick(rng, [0.02, 0.04, 0.05]); return make({ prompt: L(`Una persona de ${F} N está parada sobre ${fmt(A)} m² de zapatillas. ¿Qué presión hace sobre el piso?`, `Peteĩ tapicha ${F} N oñembo’y ${fmt(A)} m² zapatilla ári. ¿Mba’e presión ojapo yvýre?`), data: [d('F', F, 'N'), d('A', A, 'm²')], ask: 'P', formula: 'P = F / A', subst: `P = ${F} / ${fmt(A)}`, answer: F / A, unit: 'Pa' }); },

  // Arquímedes
  'arq-buoyancy': rng => { const V = pick(rng, [0.001, 0.002, 0.003, 0.005, 0.01]); return make({ prompt: L(`Un objeto de ${fmt(V)} m³ está totalmente sumergido en agua. ¿Qué empuje recibe?`, `Peteĩ objeto ${fmt(V)} m³ oike ýpe tuichakue. ¿Mba’e empuje ohupyty?`), data: [d('ρ', 1000, 'kg/m³'), d('g', G_EARTH, 'm/s²'), d('V', V, 'm³')], ask: 'E', formula: 'E = ρ · g · V', subst: `E = 1000 · 9,8 · ${fmt(V)}`, answer: 1000 * G_EARTH * V, unit: 'N' }); },
  'arq-fraction': rng => { const rho = pick(rng, [300, 450, 600, 700, 800, 920]); return make({ prompt: L(`Una madera de densidad ${rho} kg/m³ flota en agua. ¿Qué porcentaje de su volumen queda sumergido?`, `Yvyra densidad ${rho} kg/m³ ovevúi ýpe. ¿Mboy porcentaje ivolumen oike ýpe?`), data: [d('ρ_{c}', rho, 'kg/m³'), d('ρ_{agua}', 1000, 'kg/m³')], ask: '%', formula: '% = ρ_{c} / ρ_{agua} · 100', subst: `% = ${rho} / 1000 · 100`, answer: rho / 10, unit: '%' }); },
  'arq-apparent': rng => { const m = pick(rng, [2, 3, 5, 8]); const V = pick(rng, [0.0005, 0.001, 0.002]); return make({ prompt: L(`Una piedra de ${m} kg y ${fmt(V)} m³ se sumerge en agua. ¿Cuál es su peso aparente?`, `Ita ${m} kg ha ${fmt(V)} m³ oike ýpe. ¿Mboýpa ipeso aparente?`), data: [d('m', m, 'kg'), d('V', V, 'm³')], ask: 'P_{ap}', formula: 'P_{ap} = m · g − ρ · g · V', subst: `P_{ap} = ${m} · 9,8 − 1000 · 9,8 · ${fmt(V)}`, answer: m * G_EARTH - 1000 * G_EARTH * V, unit: 'N' }); },

  // Hidrodinámica
  'hd-flow': rng => { const A = pick(rng, [0.002, 0.005, 0.01, 0.02]); const v = pick(rng, [1, 1.5, 2, 3]); return make({ prompt: L(`Por un caño de ${fmt(A)} m² de sección el agua va a ${fmt(v)} m/s. ¿Cuál es el caudal?`, `Caño ${fmt(A)} m² rupi y oho ${fmt(v)} m/s-pe. ¿Mboýpa caudal?`), data: [d('A', A, 'm²'), d('v', v, 'm/s')], ask: 'Q', formula: 'Q = A · v', subst: `Q = ${fmt(A)} · ${fmt(v)}`, answer: A * v, unit: 'm³/s', decimals: 4 }); },
  'hd-continuity': rng => { const A1 = pick(rng, [4, 6, 8, 10]); const v1 = pick(rng, [1, 2, 3]); const A2 = pick(rng, [1, 2]); return make({ prompt: L(`El agua va a ${v1} m/s en un caño de ${A1} cm² que se angosta a ${A2} cm². ¿Con qué velocidad sale?`, `Y oho ${v1} m/s-pe caño ${A1} cm²-pe ipiriguáva ${A2} cm² peve. ¿Mba’e velocidad-pe osẽ?`), data: [d('A_{1}', A1, 'cm²'), d('v_{1}', v1, 'm/s'), d('A_{2}', A2, 'cm²')], ask: 'v_{2}', formula: 'v_{2} = A_{1} · v_{1} / A_{2}', subst: `v_{2} = ${A1} · ${v1} / ${A2}`, answer: A1 * v1 / A2, unit: 'm/s' }); },
  'hd-fill-time': rng => { const V = pick(rng, [500, 1000, 1500, 2000]); const Q = pick(rng, [0.5, 1, 2, 2.5]); return make({ prompt: L(`Un tanque de ${V} L se llena con un caudal de ${fmt(Q)} L/s. ¿Cuántos minutos tarda?`, `Peteĩ tanque ${V} L henyhẽ caudal ${fmt(Q)} L/s reheve. ¿Mboy minuto oipuru?`), data: [d('V', V, 'L'), d('Q', Q, 'L/s')], ask: 't', formula: 't = V / Q', subst: `t = ${V} / ${fmt(Q)} s`, answer: V / Q / 60, unit: 'min', hint: L('Calculá en segundos y dividí por 60.', 'Ecalcula segundo-pe ha edividi 60 rehe.') }); },

  // Termometría
  'temp-c2f': rng => { const c = pick(rng, [-10, 0, 25, 37, 40, 100]); return make({ prompt: L(`En Asunción hacen ${c} °C. ¿Cuánto es en grados Fahrenheit?`, `Asunción-pe oĩ ${c} °C. ¿Mboýpa Fahrenheit-pe?`), data: [d('T_{C}', c, '°C')], ask: 'T_{F}', formula: 'T_{F} = 1,8 · T_{C} + 32', subst: `T_{F} = 1,8 · ${c} + 32`, answer: 1.8 * c + 32, unit: '°F', tolAbs: 0.6 }); },
  'temp-f2c': rng => { const f = pick(rng, [32, 50, 68, 86, 98.6, 104, 212]); return make({ prompt: L(`Un termómetro importado marca ${fmt(f)} °F. ¿Cuántos °C son?`, `Termómetro importado omarka ${fmt(f)} °F. ¿Mboy °C?`), data: [d('T_{F}', f, '°F')], ask: 'T_{C}', formula: 'T_{C} = (T_{F} − 32) / 1,8', subst: `T_{C} = (${fmt(f)} − 32) / 1,8`, answer: (f - 32) / 1.8, unit: '°C', tolAbs: 0.6 }); },
  'temp-c2k': rng => { const c = pick(rng, [-273, -20, 0, 25, 100, 327]); return make({ prompt: L(`Pasá ${c} °C a la escala Kelvin.`, `Embohasa ${c} °C Kelvin escala-pe.`), data: [d('T_{C}', c, '°C')], ask: 'T', formula: 'T = T_{C} + 273', subst: `T = ${c} + 273`, answer: c + 273, unit: 'K', tolAbs: 0.6, hint: L('Sumá 273 (más preciso: 273,15).', 'Esuma 273 (273,15 precisión reheve).') }); },

  // Calorimetría
  'cal-heat': rng => { const mat = pick(rng, [{ es: 'agua', gn: 'y', c: 4186 }, { es: 'aluminio', gn: 'aluminio', c: 900 }, { es: 'hierro', gn: 'hierro', c: 450 }]); const m = pick(rng, [0.5, 1, 2]); const dT = pick(rng, [10, 20, 30, 50]); return make({ prompt: L(`¿Cuánto calor hace falta para calentar ${fmt(m)} kg de ${mat.es} en ${dT} °C? (c = ${mat.c} J/(kg·°C))`, `¿Mboy calor oikotevẽ ñamboaku hag̃ua ${fmt(m)} kg ${mat.gn} ${dT} °C? (c = ${mat.c} J/(kg·°C))`), data: [d('m', m, 'kg'), d('c', mat.c, 'J/(kg·°C)'), d('ΔT', dT, '°C')], ask: 'Q', formula: 'Q = m · c · ΔT', subst: `Q = ${fmt(m)} · ${mat.c} · ${dT}`, answer: m * mat.c * dT, unit: 'J' }); },
  'cal-mix': rng => { const m1 = pick(rng, [0.2, 0.5, 1]); const T1 = pick(rng, [70, 80, 90]); const m2 = pick(rng, [0.3, 0.5, 1, 1.5]); const T2 = pick(rng, [10, 15, 20, 25]); return make({ prompt: L(`Mezclás ${fmt(m1)} kg de agua a ${T1} °C con ${fmt(m2)} kg de agua a ${T2} °C. ¿A qué temperatura llegan?`, `Rembojehe’a ${fmt(m1)} kg y ${T1} °C-pe ${fmt(m2)} kg y ${T2} °C-pe ndive. ¿Mba’e temperatura-pe og̃uahẽ?`), data: [d('m_{1}', m1, 'kg'), d('T_{1}', T1, '°C'), d('m_{2}', m2, 'kg'), d('T_{2}', T2, '°C')], ask: 'T_{eq}', formula: 'T_{eq} = (m_{1}T_{1} + m_{2}T_{2}) / (m_{1} + m_{2})', subst: `T_{eq} = (${fmt(m1)} · ${T1} + ${fmt(m2)} · ${T2}) / (${fmt(m1)} + ${fmt(m2)})`, answer: (m1 * T1 + m2 * T2) / (m1 + m2), unit: '°C', hint: L('Es la misma sustancia: el calor específico se cancela.', 'Peteĩ sustancia: calor específico ojecancela.') }); },
  'cal-latent': rng => { const m = pick(rng, [0.1, 0.2, 0.5, 1]); return make({ prompt: L(`¿Cuánto calor hace falta para derretir ${fmt(m)} kg de hielo a 0 °C? (L = 334 000 J/kg)`, `¿Mboy calor oikotevẽ ñamboyku hag̃ua ${fmt(m)} kg hielo 0 °C-pe? (L = 334 000 J/kg)`), data: [d('m', m, 'kg'), d('L', 334000, 'J/kg')], ask: 'Q', formula: 'Q = m · L', subst: `Q = ${fmt(m)} · 334 000`, answer: m * 334000, unit: 'J' }); },
  'cal-joule': rng => { const cal = pick(rng, [100, 250, 500, 1000, 2000]); return make({ prompt: L(`¿Cuántos joules son ${cal} calorías? (1 cal = 4,186 J)`, `¿Mboy joule ha’e ${cal} caloría? (1 cal = 4,186 J)`), data: [d('Q', cal, 'cal')], ask: 'Q', formula: 'Q (J) = Q (cal) · 4,186', subst: `Q = ${cal} · 4,186`, answer: cal * 4.186, unit: 'J' }); },

  // Dilatación
  'dil-delta': rng => { const mat = pick(rng, [{ es: 'acero', gn: 'acero', a: 1.2e-5 }, { es: 'aluminio', gn: 'aluminio', a: 2.4e-5 }, { es: 'cobre', gn: 'cobre', a: 1.7e-5 }]); const L0 = pick(rng, [2, 5, 10, 20, 50]); const dT = pick(rng, [20, 30, 40, 50]); return make({ prompt: L(`Una barra de ${mat.es} de ${L0} m se calienta ${dT} °C. ¿Cuántos milímetros se alarga? (α = ${fmt(mat.a)} /°C)`, `Barra ${mat.gn} ${L0} m haku ${dT} °C. ¿Mboy milímetro ipukuve? (α = ${fmt(mat.a)} /°C)`), data: [d('α', mat.a, '/°C'), d('L_{0}', L0, 'm'), d('ΔT', dT, '°C')], ask: 'ΔL', formula: 'ΔL = α · L_{0} · ΔT', subst: `ΔL = ${fmt(mat.a)} · ${L0} · ${dT} m`, answer: mat.a * L0 * dT * 1000, unit: 'mm', hint: L('Calculá en metros y pasá a milímetros (× 1000).', 'Ecalcula metro-pe ha embohasa milímetro-pe (× 1000).') }); },
  'dil-final': rng => { const L0 = pick(rng, [1, 2, 5, 10]); const dT = pick(rng, [50, 80, 100]); const a = 2.4e-5; return make({ prompt: L(`Un riel de aluminio de ${L0} m (α = 2,4 × 10⁻⁵ /°C) sube ${dT} °C. ¿Cuál es su longitud final?`, `Riel aluminio ${L0} m (α = 2,4 × 10⁻⁵ /°C) ojupi ${dT} °C. ¿Mboýpa ilongitud final?`), data: [d('L_{0}', L0, 'm'), d('α', a, '/°C'), d('ΔT', dT, '°C')], ask: 'L', formula: 'L = L_{0} · (1 + α · ΔT)', subst: `L = ${L0} · (1 + 2,4 × 10⁻⁵ · ${dT})`, answer: L0 * (1 + a * dT), unit: 'm', decimals: 4, tolAbs: L0 * a * dT * 0.05 }); },

  // Termodinámica
  'td-first-law': rng => { const Q = pick(rng, [400, 500, 800, 1000, 1500]); const W = pick(rng, [100, 150, 200, 300]); return make({ prompt: L(`Un gas recibe ${Q} J de calor y realiza ${W} J de trabajo. ¿Cuánto cambia su energía interna?`, `Peteĩ gas ohupyty ${Q} J calor ha ojapo ${W} J trabajo. ¿Mboy okambia ienergía interna?`), data: [d('Q', Q, 'J'), d('W', W, 'J')], ask: 'ΔU', formula: 'ΔU = Q − W', subst: `ΔU = ${Q} − ${W}`, answer: Q - W, unit: 'J' }); },
  'td-efficiency': rng => { const Qc = pick(rng, [1000, 2000, 2500, 4000]); const W = Qc * pick(rng, [0.2, 0.25, 0.3, 0.35, 0.4]); return make({ prompt: L(`Un motor recibe ${Qc} J de calor y produce ${fmt(W)} J de trabajo. ¿Qué rendimiento tiene (%)?`, `Peteĩ motor ohupyty ${Qc} J calor ha ome’ẽ ${fmt(W)} J trabajo. ¿Mboýpa irendimiento (%)?`), data: [d('Q_{c}', Qc, 'J'), d('W', W, 'J')], ask: 'η', formula: 'η = W / Q_{c} · 100', subst: `η = ${fmt(W)} / ${Qc} · 100`, answer: W / Qc * 100, unit: '%' }); },
  'td-carnot': rng => { const Tc = pick(rng, [227, 327, 427, 527]); const Tf = pick(rng, [27, 37, 77]); return make({ prompt: L(`Una máquina de Carnot trabaja entre ${Tc} °C y ${Tf} °C. ¿Cuál es su rendimiento máximo (%)?`, `Carnot máquina omba’apo ${Tc} °C ha ${Tf} °C pa’ũme. ¿Mboýpa irendimiento máximo (%)?`), data: [d('T_{c}', Tc + 273, 'K'), d('T_{f}', Tf + 273, 'K')], ask: 'η', formula: 'η = (1 − T_{f} / T_{c}) · 100', subst: `η = (1 − ${Tf + 273} / ${Tc + 273}) · 100`, answer: (1 - (Tf + 273) / (Tc + 273)) * 100, unit: '%', hint: L('Pasá las temperaturas a kelvin primero.', 'Embohasa temperatura kelvin-pe raẽ.') }); },

  // Gases
  'gas-boyle': rng => { const P1 = pick(rng, [1, 1.5, 2]); const V1 = pick(rng, [6, 8, 10, 12]); const V2 = pick(rng, [2, 3, 4, 5]); return make({ prompt: L(`Un gas a ${fmt(P1)} atm ocupa ${V1} L. Si se comprime a ${V2} L a temperatura constante, ¿qué presión tendrá?`, `Peteĩ gas ${fmt(P1)} atm-pe oipuru ${V1} L. Oñemichĩramo ${V2} L peve temperatura constante-pe, ¿mba’e presión oguerekóta?`), data: [d('P_{1}', P1, 'atm'), d('V_{1}', V1, 'L'), d('V_{2}', V2, 'L')], ask: 'P_{2}', formula: 'P_{2} = P_{1} · V_{1} / V_{2}', subst: `P_{2} = ${fmt(P1)} · ${V1} / ${V2}`, answer: P1 * V1 / V2, unit: 'atm' }); },
  'gas-charles': rng => { const V1 = pick(rng, [2, 3, 4, 5]); const T1 = pick(rng, [0, 27, 20]); const T2 = pick(rng, [77, 100, 127, 177]); return make({ prompt: L(`Un globo de ${V1} L a ${T1} °C se calienta a ${T2} °C a presión constante. ¿Qué volumen tendrá?`, `Globo ${V1} L ${T1} °C-pe haku ${T2} °C peve presión constante-pe. ¿Mba’e volumen oguerekóta?`), data: [d('V_{1}', V1, 'L'), d('T_{1}', T1 + 273, 'K'), d('T_{2}', T2 + 273, 'K')], ask: 'V_{2}', formula: 'V_{2} = V_{1} · T_{2} / T_{1}', subst: `V_{2} = ${V1} · ${T2 + 273} / ${T1 + 273}`, answer: V1 * (T2 + 273) / (T1 + 273), unit: 'L', hint: L('Temperaturas en kelvin.', 'Temperatura kelvin-pe.') }); },
  'gas-gaylussac': rng => { const P1 = pick(rng, [1, 2, 2.5]); const T1 = pick(rng, [27, 17]); const T2 = pick(rng, [87, 127, 177]); return make({ prompt: L(`Un aerosol a ${fmt(P1)} atm y ${T1} °C queda al sol hasta ${T2} °C (volumen constante). ¿Qué presión alcanza?`, `Aerosol ${fmt(P1)} atm ha ${T1} °C-pe opyta kuarahy-pe ${T2} °C peve (volumen constante). ¿Mba’e presión ohupyty?`), data: [d('P_{1}', P1, 'atm'), d('T_{1}', T1 + 273, 'K'), d('T_{2}', T2 + 273, 'K')], ask: 'P_{2}', formula: 'P_{2} = P_{1} · T_{2} / T_{1}', subst: `P_{2} = ${fmt(P1)} · ${T2 + 273} / ${T1 + 273}`, answer: P1 * (T2 + 273) / (T1 + 273), unit: 'atm' }); },
  'gas-work': rng => { const P = pick(rng, [1e5, 2e5, 1.5e5]); const dV = pick(rng, [0.001, 0.002, 0.005, 0.01]); return make({ prompt: L(`Un gas a presión constante de ${fmt(P)} Pa se expande ${fmt(dV)} m³. ¿Qué trabajo realiza?`, `Gas presión constante ${fmt(P)} Pa-pe ojepyso ${fmt(dV)} m³. ¿Mba’e trabajo ojapo?`), data: [d('P', P, 'Pa'), d('ΔV', dV, 'm³')], ask: 'W', formula: 'W = P · ΔV', subst: `W = ${fmt(P)} · ${fmt(dV)}`, answer: P * dV, unit: 'J' }); },

  // Luz
  'luz-time': rng => { const body = pick(rng, [{ es: 'la Luna (3,84 × 10⁸ m)', gn: 'Jasy (3,84 × 10⁸ m)', d: 3.84e8 }, { es: 'el Sol (1,5 × 10¹¹ m)', gn: 'Kuarahy (1,5 × 10¹¹ m)', d: 1.5e11 }, { es: 'un satélite a 3,6 × 10⁷ m', gn: 'satélite 3,6 × 10⁷ m-pe', d: 3.6e7 }]); return make({ prompt: L(`¿Cuánto tarda la luz en llegar desde ${body.es} hasta nosotros?`, `¿Mboy tiempo tesape og̃uahẽ ${body.gn}-gui ñandéve?`), data: [d('d', body.d, 'm'), d('c', C_LIGHT, 'm/s')], ask: 't', formula: 't = d / c', subst: `t = ${fmt(body.d)} / 3 × 10⁸`, answer: body.d / C_LIGHT, unit: 's' }); },
  'luz-index': rng => { const v = pick(rng, [2e8, 2.25e8, 1.24e8, 1.5e8]); return make({ prompt: L(`La luz viaja a ${fmt(v)} m/s dentro de un material. ¿Cuál es su índice de refracción?`, `Tesape oho ${fmt(v)} m/s-pe peteĩ material ryepýpe. ¿Mboýpa iíndice de refracción?`), data: [d('c', C_LIGHT, 'm/s'), d('v', v, 'm/s')], ask: 'n', formula: 'n = c / v', subst: `n = 3 × 10⁸ / ${fmt(v)}`, answer: C_LIGHT / v }); },
  'luz-speed-medium': rng => { const m = pick(rng, [{ es: 'agua', gn: 'y', n: 1.33 }, { es: 'vidrio', gn: 'vidrio', n: 1.5 }, { es: 'diamante', gn: 'diamante', n: 2.42 }]); return make({ prompt: L(`¿A qué velocidad (km/s) viaja la luz en ${m.es} (n = ${fmt(m.n)})?`, `¿Mba’e velocidad-pe (km/s) oho tesape ${m.gn}-pe (n = ${fmt(m.n)})?`), data: [d('c', 300000, 'km/s'), d('n', m.n)], ask: 'v', formula: 'v = c / n', subst: `v = 300 000 / ${fmt(m.n)}`, answer: 300000 / m.n, unit: 'km/s', decimals: 0 }); },

  // Reflexión
  'refl-image': rng => { const f = pick(rng, [10, 15, 20]); const dO = f * pick(rng, [1.5, 2, 3, 4]); return make({ prompt: L(`Un espejo cóncavo tiene f = ${f} cm. Ponés un objeto a ${fmt(dO)} cm. ¿A qué distancia se forma la imagen?`, `Espejo cóncavo f = ${f} cm. Remoĩ objeto ${fmt(dO)} cm-pe. ¿Mboy distancia-pe oñemoheñói imagen?`), data: [d('f', f, 'cm'), d('d_{o}', dO, 'cm')], ask: 'd_{i}', formula: '1/d_{i} = 1/f − 1/d_{o}', subst: `1/d_{i} = 1/${f} − 1/${fmt(dO)}`, answer: 1 / (1 / f - 1 / dO), unit: 'cm' }); },
  'refl-magnification': rng => { const dO = pick(rng, [20, 30, 40, 60]); const di = pick(rng, [12, 15, 20, 30]); return make({ prompt: L(`En un espejo, el objeto está a ${dO} cm y la imagen real a ${di} cm. ¿Cuál es el aumento?`, `Espejo-pe, objeto oĩ ${dO} cm-pe ha imagen real ${di} cm-pe. ¿Mboýpa aumento?`), data: [d('d_{o}', dO, 'cm'), d('d_{i}', di, 'cm')], ask: 'A', formula: 'A = −d_{i} / d_{o}', subst: `A = −${di} / ${dO}`, answer: -di / dO, hint: L('El signo negativo indica imagen invertida.', 'Signo negativo ohechauka imagen ojere.') }); },
  'refl-focal': rng => { const R = pick(rng, [20, 30, 40, 60, 80]); return make({ prompt: L(`Un espejo esférico tiene radio de curvatura ${R} cm. ¿Cuál es su distancia focal?`, `Espejo esférico radio de curvatura ${R} cm. ¿Mboýpa idistancia focal?`), data: [d('R', R, 'cm')], ask: 'f', formula: 'f = R / 2', subst: `f = ${R} / 2`, answer: R / 2, unit: 'cm' }); },

  // Refracción
  'refr-snell': rng => { const th1 = pick(rng, [30, 40, 45, 60]); const m = pick(rng, [{ es: 'agua', gn: 'y', n: 1.33 }, { es: 'vidrio', gn: 'vidrio', n: 1.5 }]); const th2 = Math.asin(Math.sin(th1 * DEG) / m.n) / DEG; return make({ prompt: L(`Un rayo pasa del aire (n = 1) al ${m.es} (n = ${fmt(m.n)}) con ${th1}° respecto a la normal. ¿Con qué ángulo se refracta?`, `Rayo ohasa aire-gui (n = 1) ${m.gn}-pe (n = ${fmt(m.n)}) ${th1}° normal-gui. ¿Mba’e ángulo-pe ijere?`), data: [d('n_{1}', 1), d('θ_{1}', th1, '°'), d('n_{2}', m.n)], ask: 'θ_{2}', formula: 'sen θ_{2} = n_{1} · sen θ_{1} / n_{2}', subst: `sen θ_{2} = 1 · sen ${th1}° / ${fmt(m.n)}`, answer: th2, unit: '°', decimals: 1, tolAbs: 0.6 }); },
  'refr-critical': rng => { const m = pick(rng, [{ es: 'agua', gn: 'y', n: 1.33 }, { es: 'vidrio', gn: 'vidrio', n: 1.5 }, { es: 'diamante', gn: 'diamante', n: 2.42 }]); return make({ prompt: L(`¿Cuál es el ángulo crítico para que la luz que sale del ${m.es} (n = ${fmt(m.n)}) al aire se refleje totalmente?`, `¿Mboýpa ángulo crítico tesape osẽva ${m.gn}-gui (n = ${fmt(m.n)}) aire-pe ojereflejá hag̃ua tuichakue?`), data: [d('n_{1}', m.n), d('n_{2}', 1)], ask: 'θ_{c}', formula: 'sen θ_{c} = n_{2} / n_{1}', subst: `sen θ_{c} = 1 / ${fmt(m.n)}`, answer: Math.asin(1 / m.n) / DEG, unit: '°', decimals: 1, tolAbs: 0.6 }); },
  'refr-index': rng => { const th1 = pick(rng, [30, 45, 60]); const n = pick(rng, [1.33, 1.5, 1.6]); const th2 = Math.asin(Math.sin(th1 * DEG) / n) / DEG; const t2 = Math.round(th2 * 10) / 10; return make({ prompt: L(`Un rayo entra desde el aire con ${th1}° y se refracta con ${fmt(t2, 1)}° (ángulos con la normal). ¿Índice de refracción del material?`, `Rayo oike aire-gui ${th1}° reheve ha ijere ${fmt(t2, 1)}° (ángulo normal ndive). ¿Material índice de refracción?`), data: [d('θ_{1}', th1, '°'), d('θ_{2}', t2, '°', 1)], ask: 'n_{2}', formula: 'n_{2} = sen θ_{1} / sen θ_{2}', subst: `n_{2} = sen ${th1}° / sen ${fmt(t2, 1)}°`, answer: Math.sin(th1 * DEG) / Math.sin(t2 * DEG) }); },

  // Lentes
  'lens-image': rng => { const f = pick(rng, [10, 12, 15, 20]); const dO = f * pick(rng, [1.5, 2, 2.5, 3]); return make({ prompt: L(`Una lente convergente de f = ${f} cm forma la imagen de un objeto ubicado a ${fmt(dO)} cm. ¿A qué distancia de la lente queda la imagen?`, `Lente convergente f = ${f} cm ojapo imagen objeto oĩva ${fmt(dO)} cm-pe. ¿Mboy distancia-pe opyta imagen?`), data: [d('f', f, 'cm'), d('d_{o}', dO, 'cm')], ask: 'd_{i}', formula: '1/d_{i} = 1/f − 1/d_{o}', subst: `1/d_{i} = 1/${f} − 1/${fmt(dO)}`, answer: 1 / (1 / f - 1 / dO), unit: 'cm' }); },
  'lens-power': rng => { const f = pick(rng, [-50, -25, 20, 25, 40, 50]); return make({ prompt: L(`Una lente tiene distancia focal de ${f} cm. ¿Cuál es su potencia en dioptrías?`, `Lente distancia focal ${f} cm. ¿Mboýpa ipotencia dioptría-pe?`), data: [d('f', f / 100, 'm')], ask: 'P', formula: 'P = 1 / f', subst: `P = 1 / ${fmt(f / 100)}`, answer: 100 / f, unit: 'D', hint: L('La focal tiene que estar en metros.', 'Focal oĩva’erã metro-pe.') }); },
  'lens-magnification': rng => { const f = pick(rng, [10, 20]); const dO = f * pick(rng, [2, 3, 4]); const di = 1 / (1 / f - 1 / dO); return make({ prompt: L(`Lente convergente de f = ${f} cm y objeto a ${dO} cm. ¿Cuál es el aumento de la imagen?`, `Lente convergente f = ${f} cm ha objeto ${dO} cm-pe. ¿Mboýpa imagen aumento?`), data: [d('f', f, 'cm'), d('d_{o}', dO, 'cm')], ask: 'A', formula: 'A = −d_{i} / d_{o}', subst: `d_{i} = ${fmt(di)} cm → A = −${fmt(di)} / ${dO}`, answer: -di / dO }); },

  // Ondas
  'wave-speed': rng => { const lambda = pick(rng, [0.5, 1, 1.5, 2, 3]); const f = pick(rng, [2, 4, 5, 10, 20]); return make({ prompt: L(`Una onda en una cuerda tiene λ = ${fmt(lambda)} m y f = ${f} Hz. ¿A qué velocidad se propaga?`, `Cuerda onda λ = ${fmt(lambda)} m ha f = ${f} Hz. ¿Mba’e velocidad-pe oho?`), data: [d('λ', lambda, 'm'), d('f', f, 'Hz')], ask: 'v', formula: 'v = λ · f', subst: `v = ${fmt(lambda)} · ${f}`, answer: lambda * f, unit: 'm/s' }); },
  'wave-lambda': rng => { const v = pick(rng, [3e8, 340, 1500]); const f = v === 3e8 ? pick(rng, [9.97e7, 6e8, 1e9]) : pick(rng, [170, 340, 500, 1000]); const what = v === 3e8 ? L('una radio FM/onda electromagnética', 'radio FM/onda electromagnética') : v === 340 ? L('el sonido en el aire', 'sonido aire-pe') : L('el sonido en el agua', 'sonido ýpe'); return make({ prompt: L(`¿Qué longitud de onda tiene ${what.es} de frecuencia ${fmt(f)} Hz (v = ${fmt(v)} m/s)?`, `¿Mba’e longitud de onda oguereko ${what.gn} frecuencia ${fmt(f)} Hz (v = ${fmt(v)} m/s)?`), data: [d('v', v, 'm/s'), d('f', f, 'Hz')], ask: 'λ', formula: 'λ = v / f', subst: `λ = ${fmt(v)} / ${fmt(f)}`, answer: v / f, unit: 'm' }); },
  'wave-period': rng => { const f = pick(rng, [0.5, 2, 4, 5, 10, 50]); return make({ prompt: L(`Una boya sube y baja con una frecuencia de ${fmt(f)} Hz. ¿Cuál es el período?`, `Peteĩ boya ojupi ha oguejy frecuencia ${fmt(f)} Hz reheve. ¿Mboýpa período?`), data: [d('f', f, 'Hz')], ask: 'T', formula: 'T = 1 / f', subst: `T = 1 / ${fmt(f)}`, answer: 1 / f, unit: 's' }); },

  // Acústica
  'ac-echo': rng => { const t = pick(rng, [0.5, 1, 1.5, 2, 3]); return make({ prompt: L(`Gritás frente a un cerro y escuchás el eco ${fmt(t)} s después. ¿A qué distancia está el cerro? (v = 340 m/s)`, `Resapukái cerro renondépe ha rehendu eco ${fmt(t)} s rire. ¿Mboy distancia-pe oĩ cerro? (v = 340 m/s)`), data: [d('v', V_SOUND, 'm/s'), d('t', t, 's')], ask: 'd', formula: 'd = v · t / 2', subst: `d = 340 · ${fmt(t)} / 2`, answer: V_SOUND * t / 2, unit: 'm', hint: L('El sonido va y vuelve: dividí por 2.', 'Sonido oho ha ou: edividi 2 rehe.') }); },
  'ac-doppler': rng => { const f = pick(rng, [500, 600, 700, 800]); const vs = pick(rng, [10, 20, 25, 30]); return make({ prompt: L(`Una ambulancia con sirena de ${f} Hz se acerca a ${vs} m/s. ¿Qué frecuencia escucha una persona parada? (v = 340 m/s)`, `Ambulancia sirena ${f} Hz oñemboja ${vs} m/s-pe. ¿Mba’e frecuencia ohendu tapicha opytáva? (v = 340 m/s)`), data: [d('f', f, 'Hz'), d('v_{f}', vs, 'm/s'), d('v', V_SOUND, 'm/s')], ask: 'f′', formula: 'f′ = f · v / (v − v_{f})', subst: `f′ = ${f} · 340 / (340 − ${vs})`, answer: f * V_SOUND / (V_SOUND - vs), unit: 'Hz' }); },
  'ac-lambda': rng => { const f = pick(rng, [85, 170, 340, 680, 1000]); return make({ prompt: L(`¿Qué longitud de onda tiene un sonido de ${f} Hz en el aire? (v = 340 m/s)`, `¿Mba’e longitud de onda oguereko sonido ${f} Hz aire-pe? (v = 340 m/s)`), data: [d('v', V_SOUND, 'm/s'), d('f', f, 'Hz')], ask: 'λ', formula: 'λ = v / f', subst: `λ = 340 / ${f}`, answer: V_SOUND / f, unit: 'm' }); },

  // Electrización
  'elz-charge': rng => { const n = pick(rng, [2, 3, 5, 6.25]) * 1e13; return make({ prompt: L(`Un globo frotado gana ${fmt(n)} electrones. ¿Qué carga tiene, en microcoulombs (valor absoluto)?`, `Globo oñembojurúva ohupyty ${fmt(n)} electrón. ¿Mba’e carga oguereko microcoulomb-pe (valor absoluto)?`), data: [d('n', n), d('e', E_CHARGE, 'C')], ask: 'q', formula: 'q = n · e', subst: `q = ${fmt(n)} · 1,6 × 10⁻¹⁹ C`, answer: n * E_CHARGE * 1e6, unit: 'µC', hint: L('Pasá de coulombs a µC multiplicando por 10⁶.', 'Embohasa coulomb µC-pe 10⁶ rehe.') }); },
  'elz-electrons': rng => { const q = pick(rng, [1, 2, 3.2, 4.8, 8]); return make({ prompt: L(`¿Cuántos electrones faltan en un cuerpo con carga +${fmt(q)} µC?`, `¿Mboy electrón ofaltá cuerpo carga +${fmt(q)} µC-pe?`), data: [d('q', q * 1e-6, 'C'), d('e', E_CHARGE, 'C')], ask: 'n', formula: 'n = q / e', subst: `n = ${fmt(q * 1e-6)} / 1,6 × 10⁻¹⁹`, answer: q * 1e-6 / E_CHARGE }); },
  'elz-contact': rng => { const q1 = pick(rng, [8, 10, 12, 6]); const q2 = pick(rng, [-2, -4, 2, 0]); return make({ prompt: L(`Dos esferas metálicas iguales con ${q1} µC y ${q2} µC se tocan y se separan. ¿Qué carga queda en cada una?`, `Mokõi esfera metálica peteĩchagua ${q1} µC ha ${q2} µC ojopoko ha oñemomombyry. ¿Mba’e carga opyta káda peteĩme?`), data: [d('q_{1}', q1, 'µC'), d('q_{2}', q2, 'µC')], ask: 'q', formula: 'q = (q_{1} + q_{2}) / 2', subst: `q = (${q1} + ${q2}) / 2`, answer: (q1 + q2) / 2, unit: 'µC', tolAbs: 0.05 }); },

  // Coulomb
  'coul-force': rng => { const q1 = pick(rng, [1, 2, 3, 4, 5]); const q2 = pick(rng, [1, 2, 3, 6]); const r = pick(rng, [0.1, 0.2, 0.3, 0.5]); return make({ prompt: L(`Dos cargas de ${q1} µC y ${q2} µC están a ${fmt(r)} m. ¿Qué fuerza eléctrica hay entre ellas?`, `Mokõi carga ${q1} µC ha ${q2} µC oĩ ${fmt(r)} m-pe. ¿Mba’e fuerza eléctrica oĩ ojupe?`), data: [d('k', K_COULOMB, 'N·m²/C²'), d('q_{1}', q1 * 1e-6, 'C'), d('q_{2}', q2 * 1e-6, 'C'), d('d', r, 'm')], ask: 'F', formula: 'F = k · q_{1} · q_{2} / d²', subst: `F = 9 × 10⁹ · ${fmt(q1 * 1e-6)} · ${fmt(q2 * 1e-6)} / ${fmt(r)}²`, answer: K_COULOMB * q1 * 1e-6 * q2 * 1e-6 / (r * r), unit: 'N' }); },
  'coul-distance': rng => { const F = pick(rng, [0.4, 0.9, 1.2, 2]); const k = pick(rng, [2, 3]); return make({ prompt: L(`Dos cargas se atraen con ${fmt(F)} N. Si la distancia se reduce a 1/${k} de la original, ¿cuál es la nueva fuerza?`, `Mokõi carga ojoguerahauka ${fmt(F)} N reheve. Distancia oguejýramo 1/${k} peve, ¿mboýpa fuerza pyahu?`), data: [d('F', F, 'N'), d('factor', 1 / k)], ask: 'F′', formula: 'F′ = F · factor²', subst: `F′ = ${fmt(F)} · ${k}²`, answer: F * k * k, unit: 'N' }); },
  'coul-charge': rng => { const q1 = pick(rng, [2, 4, 5]); const q2 = pick(rng, [1, 3, 6]); const r = pick(rng, [0.1, 0.3]); const F = K_COULOMB * q1 * 1e-6 * q2 * 1e-6 / (r * r); return make({ prompt: L(`Una carga de ${q1} µC atrae a otra con ${fmt(F)} N a ${fmt(r)} m. ¿Cuánto vale la otra carga (en µC)?`, `Carga ${q1} µC ombyaty ambuéva ${fmt(F)} N reheve ${fmt(r)} m-pe. ¿Mboýpa ambue carga (µC-pe)?`), data: [d('F', F, 'N'), d('q_{1}', q1, 'µC'), d('d', r, 'm')], ask: 'q_{2}', formula: 'q_{2} = F · d² / (k · q_{1})', subst: `q_{2} = ${fmt(F)} · ${fmt(r)}² / (9 × 10⁹ · ${fmt(q1 * 1e-6)}) C`, answer: q2, unit: 'µC' }); },

  // Campo eléctrico
  'field-point': rng => { const Q = pick(rng, [1, 2, 4, 5]); const r = pick(rng, [0.1, 0.2, 0.3, 0.5]); return make({ prompt: L(`¿Qué campo eléctrico crea una carga de ${Q} µC a ${fmt(r)} m de distancia?`, `¿Mba’e campo eléctrico ojapo carga ${Q} µC ${fmt(r)} m-pe?`), data: [d('k', K_COULOMB, 'N·m²/C²'), d('Q', Q * 1e-6, 'C'), d('d', r, 'm')], ask: 'E', formula: 'E = k · Q / d²', subst: `E = 9 × 10⁹ · ${fmt(Q * 1e-6)} / ${fmt(r)}²`, answer: K_COULOMB * Q * 1e-6 / (r * r), unit: 'N/C' }); },
  'field-force': rng => { const q = pick(rng, [2, 3, 5, 10]); const E = pick(rng, [1e4, 2e4, 5e4]); return make({ prompt: L(`Una carga de ${q} µC está en un campo de ${fmt(E)} N/C. ¿Qué fuerza siente?`, `Carga ${q} µC oĩ campo ${fmt(E)} N/C-pe. ¿Mba’e fuerza ohendu?`), data: [d('q', q * 1e-6, 'C'), d('E', E, 'N/C')], ask: 'F', formula: 'F = q · E', subst: `F = ${fmt(q * 1e-6)} · ${fmt(E)}`, answer: q * 1e-6 * E, unit: 'N' }); },
  'field-distance': rng => { const E = pick(rng, [900, 3600, 1800]); const k = pick(rng, [2, 3]); return make({ prompt: L(`A cierta distancia de una carga el campo vale ${E} N/C. ¿Cuánto vale a ${k} veces esa distancia?`, `Peteĩ distancia-pe carga-gui campo ha’e ${E} N/C. ¿Mboýpa ${k} veces upe distancia-pe?`), data: [d('E', E, 'N/C'), d('factor', k)], ask: 'E′', formula: 'E′ = E / factor²', subst: `E′ = ${E} / ${k}²`, answer: E / (k * k), unit: 'N/C' }); },

  // Potencial
  'pot-point': rng => { const Q = pick(rng, [1, 2, 3, 5]); const r = pick(rng, [0.1, 0.2, 0.3, 0.5]); return make({ prompt: L(`¿Qué potencial eléctrico crea una carga de ${Q} µC a ${fmt(r)} m?`, `¿Mba’e potencial eléctrico ojapo carga ${Q} µC ${fmt(r)} m-pe?`), data: [d('k', K_COULOMB, 'N·m²/C²'), d('Q', Q * 1e-6, 'C'), d('d', r, 'm')], ask: 'V', formula: 'V = k · Q / d', subst: `V = 9 × 10⁹ · ${fmt(Q * 1e-6)} / ${fmt(r)}`, answer: K_COULOMB * Q * 1e-6 / r, unit: 'V' }); },
  'pot-uniform': rng => { const E = pick(rng, [500, 1000, 2000, 5000]); const dd = pick(rng, [0.01, 0.02, 0.05]); return make({ prompt: L(`Entre dos placas separadas ${fmt(dd)} m el campo es ${E} N/C. ¿Qué diferencia de potencial hay?`, `Mokõi placa ${fmt(dd)} m-pe ojoavýva pa’ũme campo ha’e ${E} N/C. ¿Mba’e diferencia de potencial oĩ?`), data: [d('E', E, 'N/C'), d('d', dd, 'm')], ask: 'ΔV', formula: 'ΔV = E · d', subst: `ΔV = ${E} · ${fmt(dd)}`, answer: E * dd, unit: 'V' }); },
  'pot-energy': rng => { const q = pick(rng, [0.5, 1, 2, 3]); const V = pick(rng, [1.5, 9, 12, 220]); return make({ prompt: L(`¿Qué energía gana una carga de ${fmt(q)} C al pasar por una diferencia de potencial de ${fmt(V)} V?`, `¿Mba’e energía ohupyty carga ${fmt(q)} C ohasávo diferencia de potencial ${fmt(V)} V?`), data: [d('q', q, 'C'), d('V', V, 'V')], ask: 'U', formula: 'U = q · V', subst: `U = ${fmt(q)} · ${fmt(V)}`, answer: q * V, unit: 'J' }); },

  // Condensadores
  'cap-charge': rng => { const C = pick(rng, [2, 4.7, 10, 22, 100]); const V = pick(rng, [5, 9, 12]); return make({ prompt: L(`Un condensador de ${fmt(C)} µF se conecta a ${V} V. ¿Qué carga almacena?`, `Condensador ${fmt(C)} µF ojeconecta ${V} V-pe. ¿Mba’e carga oñongatu?`), data: [d('C', C, 'µF'), d('V', V, 'V')], ask: 'Q', formula: 'Q = C · V', subst: `Q = ${fmt(C)} · ${V}`, answer: C * V, unit: 'µC' }); },
  'cap-series': rng => { const C1 = pick(rng, [2, 3, 4, 6]); const C2 = pick(rng, [3, 4, 6, 12]); return make({ prompt: L(`Dos condensadores de ${C1} µF y ${C2} µF se conectan en serie. ¿Capacidad equivalente?`, `Mokõi condensador ${C1} µF ha ${C2} µF serie-pe. ¿Capacidad equivalente?`), data: [d('C_{1}', C1, 'µF'), d('C_{2}', C2, 'µF')], ask: 'C_{s}', formula: 'C_{s} = C_{1} · C_{2} / (C_{1} + C_{2})', subst: `C_{s} = ${C1} · ${C2} / (${C1} + ${C2})`, answer: C1 * C2 / (C1 + C2), unit: 'µF' }); },
  'cap-parallel': rng => { const C1 = pick(rng, [2, 4.7, 10]); const C2 = pick(rng, [3, 5, 22]); return make({ prompt: L(`Dos condensadores de ${fmt(C1)} µF y ${C2} µF se conectan en paralelo. ¿Capacidad equivalente?`, `Mokõi condensador ${fmt(C1)} µF ha ${C2} µF paralelo-pe. ¿Capacidad equivalente?`), data: [d('C_{1}', C1, 'µF'), d('C_{2}', C2, 'µF')], ask: 'C_{p}', formula: 'C_{p} = C_{1} + C_{2}', subst: `C_{p} = ${fmt(C1)} + ${C2}`, answer: C1 + C2, unit: 'µF' }); },
  'cap-energy': rng => { const C = pick(rng, [100, 220, 470, 1000]); const V = pick(rng, [5, 9, 12, 24]); return make({ prompt: L(`¿Qué energía guarda un condensador de ${C} µF cargado a ${V} V?`, `¿Mba’e energía oñongatu condensador ${C} µF ${V} V-pe?`), data: [d('C', C * 1e-6, 'F'), d('V', V, 'V')], ask: 'U', formula: 'U = ½ C · V²', subst: `U = ½ · ${fmt(C * 1e-6)} · ${V}²`, answer: 0.5 * C * 1e-6 * V * V, unit: 'J', decimals: 4 }); },

  // Corriente
  'cur-intensity': rng => { const Q = pick(rng, [10, 20, 30, 60, 120]); const t = pick(rng, [5, 10, 20, 30, 60]); return make({ prompt: L(`Por un cable pasan ${Q} C en ${t} s. ¿Cuál es la intensidad de corriente?`, `Cable-rupi ohasa ${Q} C ${t} s-pe. ¿Mboýpa corriente intensidad?`), data: [d('Q', Q, 'C'), d('t', t, 's')], ask: 'I', formula: 'I = Q / t', subst: `I = ${Q} / ${t}`, answer: Q / t, unit: 'A' }); },
  'cur-charge': rng => { const I = pick(rng, [0.5, 1, 2, 5]); const t = pick(rng, [10, 30, 60, 120]); return make({ prompt: L(`Una lámpara consume ${fmt(I)} A durante ${t} s. ¿Cuánta carga pasó?`, `Lámpara oipuru ${fmt(I)} A ${t} s aja. ¿Mboy carga ohasa?`), data: [d('I', I, 'A'), d('t', t, 's')], ask: 'Q', formula: 'Q = I · t', subst: `Q = ${fmt(I)} · ${t}`, answer: I * t, unit: 'C' }); },
  'cur-energy': rng => { const P = pick(rng, [1000, 1500, 2000, 5500]); const min = pick(rng, [10, 15, 30, 60]); return make({ prompt: L(`Una ducha de ${P} W se usa ${min} minutos. ¿Cuántos kWh consume?`, `Ducha ${P} W ojepuru ${min} minuto. ¿Mboy kWh oipuru?`), data: [d('P', P / 1000, 'kW'), d('t', min / 60, 'h')], ask: 'E', formula: 'E = P · t', subst: `E = ${fmt(P / 1000)} · ${fmt(min / 60)}`, answer: P / 1000 * min / 60, unit: 'kWh', hint: L('Potencia en kW y tiempo en horas.', 'Potencia kW-pe ha tiempo hora-pe.') }); },

  // Ohm
  'ohm-current': rng => { const V = pick(rng, [6, 9, 12, 24, 220]); const R = pick(rng, [2, 3, 4, 10, 100]); return make({ prompt: L(`Una resistencia de ${R} Ω se conecta a ${V} V. ¿Qué corriente circula?`, `Resistencia ${R} Ω ojeconecta ${V} V-pe. ¿Mba’e corriente ohasa?`), data: [d('V', V, 'V'), d('R', R, 'Ω')], ask: 'I', formula: 'I = V / R', subst: `I = ${V} / ${R}`, answer: V / R, unit: 'A' }); },
  'ohm-voltage': rng => { const I = pick(rng, [0.5, 1, 2, 3]); const R = pick(rng, [4, 6, 10, 12, 20]); return make({ prompt: L(`Por una resistencia de ${R} Ω circulan ${fmt(I)} A. ¿Qué voltaje tiene entre sus extremos?`, `Resistencia ${R} Ω rupi ohasa ${fmt(I)} A. ¿Mba’e voltaje oguereko?`), data: [d('I', I, 'A'), d('R', R, 'Ω')], ask: 'V', formula: 'V = I · R', subst: `V = ${fmt(I)} · ${R}`, answer: I * R, unit: 'V' }); },
  'ohm-series': rng => { const R1 = pick(rng, [2, 4, 6, 10]); const R2 = pick(rng, [2, 3, 6, 8]); const V = pick(rng, [12, 24]); return make({ prompt: L(`Dos resistencias de ${R1} Ω y ${R2} Ω en serie se conectan a ${V} V. ¿Qué corriente circula?`, `Mokõi resistencia ${R1} Ω ha ${R2} Ω serie-pe ojeconecta ${V} V-pe. ¿Mba’e corriente ohasa?`), data: [d('R_{1}', R1, 'Ω'), d('R_{2}', R2, 'Ω'), d('V', V, 'V')], ask: 'I', formula: 'I = V / (R_{1} + R_{2})', subst: `I = ${V} / (${R1} + ${R2})`, answer: V / (R1 + R2), unit: 'A' }); },
  'ohm-parallel': rng => { const R1 = pick(rng, [4, 6, 10, 12, 20]); const R2 = pick(rng, [4, 12, 15, 30]); return make({ prompt: L(`Dos resistencias de ${R1} Ω y ${R2} Ω están en paralelo. ¿Cuánto vale la resistencia equivalente?`, `Mokõi resistencia ${R1} Ω ha ${R2} Ω oĩ paralelo-pe. ¿Mboýpa resistencia equivalente?`), data: [d('R_{1}', R1, 'Ω'), d('R_{2}', R2, 'Ω')], ask: 'R_{p}', formula: 'R_{p} = R_{1} · R_{2} / (R_{1} + R_{2})', subst: `R_{p} = ${R1} · ${R2} / (${R1} + ${R2})`, answer: R1 * R2 / (R1 + R2), unit: 'Ω' }); },
  'ohm-power': rng => { const V = pick(rng, [12, 24, 220]); const R = pick(rng, [4, 6, 48, 100, 484]); return make({ prompt: L(`¿Qué potencia disipa una resistencia de ${R} Ω conectada a ${V} V?`, `¿Mba’e potencia odisipa resistencia ${R} Ω ${V} V-pe?`), data: [d('V', V, 'V'), d('R', R, 'Ω')], ask: 'P', formula: 'P = V² / R', subst: `P = ${V}² / ${R}`, answer: V * V / R, unit: 'W' }); },

  // Magnetismo
  'mag-wire': rng => { const I = pick(rng, [5, 10, 20, 50]); const r = pick(rng, [0.02, 0.05, 0.1, 0.2]); return make({ prompt: L(`Un cable recto lleva ${I} A. ¿Qué campo magnético hay a ${fmt(r)} m (en microteslas)?`, `Cable recto ogueraha ${I} A. ¿Mba’e campo magnético oĩ ${fmt(r)} m-pe (microtesla-pe)?`), data: [d('µ_{0}', 4 * Math.PI * 1e-7, 'T·m/A'), d('I', I, 'A'), d('d', r, 'm')], ask: 'B', formula: 'B = µ_{0} · I / (2π · d)', subst: `B = 4π × 10⁻⁷ · ${I} / (2π · ${fmt(r)}) T`, answer: 2e-7 * I / r * 1e6, unit: 'µT', hint: L('Pasá de teslas a µT multiplicando por 10⁶.', 'Embohasa tesla µT-pe 10⁶ rehe.') }); },
  'mag-force': rng => { const B = pick(rng, [0.1, 0.2, 0.5]); const I = pick(rng, [2, 5, 10]); const Lg = pick(rng, [0.2, 0.5, 1]); return make({ prompt: L(`Un cable de ${fmt(Lg)} m con ${I} A está perpendicular a un campo de ${fmt(B)} T. ¿Qué fuerza recibe?`, `Cable ${fmt(Lg)} m ${I} A reheve oĩ perpendicular campo ${fmt(B)} T-pe. ¿Mba’e fuerza ohupyty?`), data: [d('B', B, 'T'), d('I', I, 'A'), d('L', Lg, 'm')], ask: 'F', formula: 'F = B · I · L', subst: `F = ${fmt(B)} · ${I} · ${fmt(Lg)}`, answer: B * I * Lg, unit: 'N' }); },
  'mag-distance': rng => { const B1 = pick(rng, [20, 40, 60]); const d1 = pick(rng, [0.05, 0.1]); const k = pick(rng, [2, 4]); return make({ prompt: L(`A ${fmt(d1)} m de un cable el campo es ${B1} µT. ¿Cuánto vale a ${fmt(d1 * k)} m?`, `Cable-gui ${fmt(d1)} m-pe campo ha’e ${B1} µT. ¿Mboýpa ${fmt(d1 * k)} m-pe?`), data: [d('B_{1}', B1, 'µT'), d('d_{1}', d1, 'm'), d('d_{2}', d1 * k, 'm')], ask: 'B_{2}', formula: 'B_{2} = B_{1} · d_{1} / d_{2}', subst: `B_{2} = ${B1} · ${fmt(d1)} / ${fmt(d1 * k)}`, answer: B1 / k, unit: 'µT' }); },

  // Relatividad
  'rel-gamma': rng => { const beta = pick(rng, [0.6, 0.8, 0.866, 0.9, 0.99]); return make({ prompt: L(`Una nave viaja a ${fmt(beta)}·c. ¿Cuánto vale el factor de Lorentz γ?`, `Peteĩ nave oho ${fmt(beta)}·c-pe. ¿Mboýpa Lorentz factor γ?`), data: [d('v/c', beta)], ask: 'γ', formula: 'γ = 1 / √(1 − (v/c)²)', subst: `γ = 1 / √(1 − ${fmt(beta)}²)`, answer: 1 / Math.sqrt(1 - beta * beta) }); },
  'rel-time': rng => { const beta = pick(rng, [0.6, 0.8]); const t0 = pick(rng, [1, 2, 5, 10]); const g = 1 / Math.sqrt(1 - beta * beta); return make({ prompt: L(`Para la tripulación de una nave a ${fmt(beta)}·c pasan ${t0} años. ¿Cuántos años pasan en la Tierra?`, `Nave ${fmt(beta)}·c-pe tripulación-pe ohasa ${t0} ary. ¿Mboy ary ohasa Yvy-pe?`), data: [d('Δt_{0}', t0, 'años'), d('v/c', beta)], ask: 'Δt', formula: 'Δt = γ · Δt_{0}', subst: `Δt = ${fmt(g)} · ${t0}`, answer: g * t0, unit: 'años' }); },
  'rel-energy': rng => { const m = pick(rng, [0.001, 0.002, 0.01, 1]); return make({ prompt: L(`¿Cuánta energía equivale a una masa de ${fmt(m)} kg? (c = 3 × 10⁸ m/s)`, `¿Mboy energía ojoja masa ${fmt(m)} kg ndive? (c = 3 × 10⁸ m/s)`), data: [d('m', m, 'kg'), d('c', C_LIGHT, 'm/s')], ask: 'E', formula: 'E = m · c²', subst: `E = ${fmt(m)} · (3 × 10⁸)²`, answer: m * C_LIGHT * C_LIGHT, unit: 'J' }); },

  // Cuántica
  'q-photon': rng => { const f = pick(rng, [4.3, 5, 6, 7.5]) * 1e14; return make({ prompt: L(`¿Qué energía tiene un fotón de luz visible de ${fmt(f)} Hz, en electronvoltios? (1 eV = 1,6 × 10⁻¹⁹ J)`, `¿Mba’e energía oguereko fotón tesape ${fmt(f)} Hz, electronvoltio-pe? (1 eV = 1,6 × 10⁻¹⁹ J)`), data: [d('h', H_PLANCK, 'J·s'), d('f', f, 'Hz')], ask: 'E', formula: 'E = h · f', subst: `E = 6,63 × 10⁻³⁴ · ${fmt(f)} J`, answer: H_PLANCK * f / E_CHARGE, unit: 'eV', hint: L('Calculá en joules y dividí por 1,6 × 10⁻¹⁹.', 'Ecalcula joule-pe ha edividi 1,6 × 10⁻¹⁹ rehe.') }); },
  'q-photoelectric': rng => { const f = pick(rng, [1, 1.2, 1.5]) * 1e15; const phi = pick(rng, [2.3, 2.75, 4.3]); const Ec = H_PLANCK * f / E_CHARGE - phi; return make({ prompt: L(`Luz ultravioleta de ${fmt(f)} Hz ilumina un metal con función trabajo de ${fmt(phi)} eV. ¿Con qué energía cinética máxima salen los electrones (eV)?`, `Tesape ultravioleta ${fmt(f)} Hz ohesape metal función trabajo ${fmt(phi)} eV-pe. ¿Mba’e energía cinética máxima-pe osẽ electrón (eV)?`), data: [d('f', f, 'Hz'), d('φ', phi, 'eV')], ask: 'E_{c}', formula: 'E_{c} = h · f − φ', subst: `E_{c} = 6,63 × 10⁻³⁴ · ${fmt(f)} / 1,6 × 10⁻¹⁹ − ${fmt(phi)}`, answer: Ec, unit: 'eV' }); },
  'q-frequency': rng => { const E = pick(rng, [1.8, 2.5, 3.1]); return make({ prompt: L(`Un fotón tiene ${fmt(E)} eV. ¿Cuál es su frecuencia?`, `Peteĩ fotón oguereko ${fmt(E)} eV. ¿Mboýpa ifrecuencia?`), data: [d('E', E, 'eV'), d('h', H_PLANCK, 'J·s')], ask: 'f', formula: 'f = E / h', subst: `f = ${fmt(E)} · 1,6 × 10⁻¹⁹ / 6,63 × 10⁻³⁴`, answer: E * E_CHARGE / H_PLANCK, unit: 'Hz' }); },
};

export const GENERATOR_IDS = Object.keys(GENERATORS);

/** Genera el ejercicio `genId` con una semilla (mismo seed → mismo ejercicio). */
export function generateExercise(genId, seed = Date.now()) {
  const builder = GENERATORS[genId];
  if (!builder) return null;
  const rng = seededRandom(seed);
  const exercise = builder(rng);
  return { ...exercise, genId, seed, id: `${genId}#${seed}` };
}

/** Compara la respuesta del alumno con tolerancia relativa del 2 % (o la
 * absoluta del ejercicio) y también acepta el valor redondeado mostrado. */
export function checkAnswer(exercise, input) {
  const value = parseUserNumber(input);
  if (!Number.isFinite(value)) return { valid: false, correct: false };
  const expected = exercise.answer;
  const tolerance = Math.max(exercise.tolAbs ?? 0, Math.abs(expected) * 0.02, 0.5 * 10 ** -(exercise.decimals ?? 2));
  const diff = value - expected;
  const correct = Math.abs(diff) <= tolerance;
  // Pista típica: error por un factor 10, 100 o 1000 (unidades).
  const ratio = expected !== 0 ? value / expected : 0;
  const unitSlip = !correct && [10, 100, 1000, 0.1, 0.01, 0.001].some(factor => Math.abs(ratio / factor - 1) < 0.03);
  const signSlip = !correct && expected !== 0 && Math.abs(value + expected) <= tolerance;
  return { valid: true, correct, value, expected, unitSlip, signSlip };
}
